import { expect, test, type Page } from '@playwright/test';
import { readFile } from 'node:fs/promises';
import { createEntity, createProject, textToRichText } from '../../src/domain/model';
import { exportScenario, inspectScenario } from '../../src/storage/archive';
import type { ProjectData } from '../../src/domain/types';

async function nav(page:Page,name:RegExp){const menu=page.getByRole('button',{name:'メニューを開く'});if(await menu.isVisible())await menu.click();await page.getByRole('button',{name}).first().click();}
async function seed(page:Page,bytes:Uint8Array){await page.goto('./');await page.getByRole('button',{name:'保存ファイルを読み込む',exact:true}).click();await page.locator('input[type=file]').setInputFiles({name:'production.scenario',mimeType:'application/zip',buffer:Buffer.from(bytes)});await page.getByLabel('復元方法と対象への影響を確認しました').check();await page.getByRole('button',{name:'この内容で復元する',exact:true}).click();await expect(page.locator('.project-switch')).toBeVisible();}
async function open(page:Page,kind:string,name:string){await nav(page,/^資料/);await page.getByLabel('情報の種類',{exact:true}).selectOption(kind);await page.locator('.entity-card').filter({has:page.getByRole('heading',{name,exact:true})}).click();}
async function backup(page:Page){await nav(page,/^作品・保存/);await page.getByRole('tab',{name:'完全保存・復元',exact:true}).click();const pending=page.waitForEvent('download');await page.getByRole('button',{name:'完全保存ファイルを作成',exact:true}).click();return inspectScenario(new Uint8Array(await readFile((await (await pending).path())!)),{worker:false});}

test('台詞分割の入力と差分を移動・失敗から再開し、旧新ID・翻訳確認待ちをcold保存と完全ファイルで確認する',async({page})=>{
 const bytes=new Uint8Array(await readFile('tests/fixtures/rb07-production.scenario')),original=(await inspectScenario(bytes,{worker:false})).project,line=original.entities.find(e=>e.kind==='dialogue_line')!;await seed(page,bytes);await open(page,'dialogue_line',line.name);let tools=page.locator('.production-tools');await tools.locator('summary').click();await tools.getByLabel('分割する文字位置',{exact:true}).fill('4');await tools.getByLabel('台詞変更の理由',{exact:true}).fill('収録を二つの単位へ分ける');await nav(page,/^構成/);await open(page,'dialogue_line',line.name);await expect(tools.getByLabel('台詞変更の理由',{exact:true})).toHaveValue('収録を二つの単位へ分ける');await page.reload();await open(page,'dialogue_line',line.name);tools=page.locator('.production-tools');await tools.locator('summary').click();await expect(tools.getByLabel('分割する文字位置',{exact:true})).toHaveValue('4');await tools.getByRole('button',{name:'変更の影響を確認',exact:true}).click();await expect(tools).toContainText('新台詞 2件');
 await page.evaluate(()=>{const put=IDBObjectStore.prototype.put;let fail=true;IDBObjectStore.prototype.put=function(...args:Parameters<IDBObjectStore['put']>){if(fail&&this.name==='projects'){fail=false;throw new DOMException('fixture quota','QuotaExceededError');}return put.apply(this,args);};});await tools.getByRole('button',{name:'確認した変更を保存',exact:true}).click();await expect(tools.getByRole('alert')).toContainText('容量');await expect(tools).toContainText('新台詞 2件');await nav(page,/^構成/);await open(page,'dialogue_line',line.name);await tools.locator('summary').click();await tools.getByRole('button',{name:'確認した変更を保存',exact:true}).click();await expect(tools.getByRole('status').filter({hasText:'表示版を確認'})).toBeVisible();
 await page.reload();const restored=(await backup(page)).project,old=restored.entities.find(e=>e.id===line.id);expect(old?.kind==='dialogue_line'&&old.data.replacedByLineIds).toHaveLength(2);expect(old?.status).toBe('rejected');const sourceIds=old?.kind==='dialogue_line'?old.data.replacedByLineIds!:[];expect(restored.entities.find(e=>e.kind==='scene'&&e.data.dialogueLineIds?.includes(sourceIds[0]))).toBeTruthy();expect(restored.entities.filter(e=>e.kind==='localization'||e.kind==='recording').every(e=>(e.kind==='localization'||e.kind==='recording')&&e.data.stage==='needs_review')).toBe(true);expect(restored.snapshots).toEqual(original.snapshots);
});

test('資料の取得日時と実動画bytesを通常保存し、再読込で安全な動画表示と不足状態を区別する',async({page})=>{
 const project=createProject('動画と取得日時の通常操作'),source=createEntity(project.projectId,'source','取得した映像資料',{sourceType:'file',locator:'作者作成fixture',accessedAt:'2026-10-08T11:00:00Z',excerptLocation:'0〜500 ms',interpretation:textToRichText('青い単色の映像'),redistributionAllowed:true});source.status='confirmed';project.entities.push(source);await seed(page,await exportScenario(project));await open(page,'source',source.name);const tools=page.locator('.production-tools');await tools.locator('summary').click();await tools.getByLabel('素材ファイルを選ぶ',{exact:true}).setInputFiles('tests/fixtures/media/fixture-blue.mp4');await tools.getByRole('button',{name:'変更の影響を確認',exact:true}).click();await tools.getByRole('button',{name:'確認した変更を保存',exact:true}).click();await expect(tools.getByRole('status').filter({hasText:'表示版を確認'})).toBeVisible();await expect(page.getByLabel('資料を取得した日時',{exact:true})).toHaveValue('2026-10-08T11:00:00Z');await page.reload();let restored=(await backup(page));expect(restored.assets).toHaveLength(1);expect(restored.project.entities.find(e=>e.id===source.id)).toMatchObject({data:{accessedAt:'2026-10-08T11:00:00Z'}});const asset=restored.project.entities.find(e=>e.kind==='attachment')!;await open(page,'attachment',asset.name);const video=page.locator('.detail-panel video');await expect(video).toBeVisible();await expect.poll(()=>video.evaluate((element:HTMLVideoElement)=>element.readyState)).toBeGreaterThanOrEqual(1);expect(await video.evaluate((element:HTMLVideoElement)=>element.videoWidth)).toBe(160);expect(await video.evaluate((element:HTMLVideoElement)=>element.duration)).toBeCloseTo(.5,1);
});

test('現在原文を選び直した翻訳をhash承認し、期限外・没用語を除いたUnicode候補を指摘版ごと原子保存する',async({page})=>{
 const p=createProject('制作確認の通常操作'),line=createEntity(p.projectId,'dialogue_line','確認する台詞',{text:textToRichText('😀赤き扉')}),translation=createEntity(p.projectId,'localization','確認する翻訳',{sourceLineId:line.id,language:'en',sourceHash:'0'.repeat(64),text:textToRichText('Red door'),stage:'needs_review'}),term=createEntity(p.projectId,'terminology','採用する用語',{canonical:'赤い扉',variants:['赤き扉'],reading:'あかいとびら',validity:{worldRange:{start:'10',end:'20'},routeCondition:null,presentationAnchor:null}}),rejected=createEntity(p.projectId,'terminology','没の用語',{canonical:'赤き扉',reading:'ぼつ'});[line,translation,term].forEach(e=>e.status='confirmed');rejected.status='rejected';p.entities.push(line,translation,term,rejected);await seed(page,await exportScenario(p));await open(page,'localization',translation.name);const tools=page.locator('.production-tools');await tools.locator('summary').click();await tools.getByRole('button',{name:'現在原文とhashを確認',exact:true}).click();await expect(tools).toContainText('😀赤き扉');await tools.getByRole('button',{name:'確認した変更を保存',exact:true}).click();await expect(tools.getByRole('status').filter({hasText:'表示版を確認'})).toBeVisible();await nav(page,/^構成/);await page.getByRole('tab',{name:'制作',exact:true}).click();const review=page.locator('.production-review');await review.getByLabel('検査時点の世界内tick',{exact:true}).fill('9');await review.getByRole('button',{name:'口調・用語の候補を検査',exact:true}).click();await expect(review).toContainText('候補 0件');await review.getByLabel('検査時点の世界内tick',{exact:true}).fill('10');await review.getByRole('button',{name:'口調・用語の候補を検査',exact:true}).click();await expect(review).toContainText('候補 2件');await expect(review).not.toContainText('ぼつ');await review.getByRole('button',{name:'候補を指摘として保存',exact:true}).first().click();await expect(review.getByRole('status').filter({hasText:'表示版を確認'})).toBeVisible();await page.reload();const saved=(await backup(page)).project;expect(saved.entities.find(e=>e.id===translation.id)).toMatchObject({data:{stage:'reviewed'}});const issue=saved.entities.find(e=>e.kind==='review');expect(issue?.kind==='review'&&issue.data.target).toMatchObject({entityId:line.id,start:1,end:4});expect(issue?.kind==='review'&&saved.snapshots.some(s=>s.id===issue.data.targetVersionId)).toBe(true);
});
